import { booleanAttribute, computed, Directive, inject, input } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { SidebarMenuButtonPassThrough } from 'primeng/types/sidebar';
import { SidebarMenuItem } from './sidebar-menu-item';
import { SIDEBAR_MENU_ITEM_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenuButton is a helper directive for Sidebar component.
 * @group Components
 */
@Directive({
    selector: '[pSidebarMenuButton]',
    standalone: true,
    host: {
        '[class]': "cx('menuButton')",
        '[attr.data-active]': 'dataActive()',
        '(click)': 'onClick($event)'
    },
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarMenuButton }]
})
export class SidebarMenuButton extends BaseComponent<SidebarMenuButtonPassThrough> {
    componentName = 'SidebarMenuButton';

    bindDirectiveInstance = inject(Bind, { optional: true, self: true }) ?? undefined;

    _componentStyle = inject(SidebarStyle);

    pcMenuItem = inject<SidebarMenuItem>(SIDEBAR_MENU_ITEM_INSTANCE, { optional: true }) ?? undefined;

    /**
     * Whether this button represents the active menu entry.
     * @defaultValue false
     * @group Props
     */
    isActive = input(false, { transform: booleanAttribute });

    dataActive = computed(() => (this.isActive() ? 'true' : null));

    onAfterViewChecked(): void {
        this.bindDirectiveInstance?.setAttrs(this.ptm('root'));
    }

    onClick(event: Event): void {
        if (this.pcMenuItem?.collapsible()) {
            this.pcMenuItem.toggle();
        }
    }
}
