import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarAsidePassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_ASIDE_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarAside is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-aside',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('aside')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_ASIDE_INSTANCE, useExisting: SidebarAside }, { provide: PARENT_INSTANCE, useExisting: SidebarAside }]
})
export class SidebarAside extends BaseComponent<SidebarAsidePassThrough> {
    componentName = 'SidebarAside';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
