import { booleanAttribute, computed, Directive, inject, input } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { SidebarMenuSubButtonPassThrough } from 'primeng/types/sidebar';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenuSubButton is a helper directive for Sidebar component.
 * @group Components
 */
@Directive({
    selector: '[pSidebarMenuSubButton]',
    standalone: true,
    host: {
        '[class]': "cx('menuSubButton')",
        '[attr.data-active]': 'dataActive()',
        '[attr.data-size]': 'dataSize()'
    },
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarMenuSubButton }]
})
export class SidebarMenuSubButton extends BaseComponent<SidebarMenuSubButtonPassThrough> {
    componentName = 'SidebarMenuSubButton';

    bindDirectiveInstance = inject(Bind, { optional: true, self: true }) ?? undefined;

    _componentStyle = inject(SidebarStyle);

    /**
     * Whether this button represents the active sub-menu entry.
     * @defaultValue false
     * @group Props
     */
    isActive = input(false, { transform: booleanAttribute });
    /**
     * Optional size variant.
     * @group Props
     */
    size = input<'sm' | 'md'>('md');

    dataActive = computed(() => (this.isActive() ? 'true' : null));

    dataSize = computed(() => (this.size() === 'sm' ? 'sm' : null));

    onAfterViewChecked(): void {
        this.bindDirectiveInstance?.setAttrs(this.ptm('root'));
    }
}
