import { isPlatformBrowser } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, effect, inject, ViewEncapsulation } from '@angular/core';
import { createMotion, type MotionInstance } from '@primeuix/motion';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarBackdropPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_INSTANCE, SIDEBAR_LAYOUT_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarBackdrop is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-backdrop',
    standalone: true,
    imports: [BindModule],
    template: ``,
    host: {
        '[class]': "cx('backdrop')",
        '(click)': 'onClick($event)'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarBackdrop }]
})
export class SidebarBackdrop extends BaseComponent<SidebarBackdropPassThrough> {
    componentName = 'SidebarBackdrop';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    private pcSidebar: any = inject(SIDEBAR_INSTANCE, { optional: true });

    private layout: any = inject(SIDEBAR_LAYOUT_INSTANCE, { optional: true });

    visible = computed(() => {
        if (this.pcSidebar) return this.pcSidebar.open();
        return !!this.layout?.isAnyOpen();
    });

    private motion: MotionInstance | undefined;
    private isInitialMount = true;

    constructor() {
        super();

        effect(() => {
            const show = this.visible();
            if (!isPlatformBrowser(this.platformId)) return;
            const el = this.el?.nativeElement as HTMLElement | undefined;
            if (!el) return;

            if (!this.motion) {
                this.motion = createMotion(el, {
                    name: 'p-overlay-mask',
                    autoHeight: false,
                    autoWidth: false
                });
            }

            if (show) {
                el.style.removeProperty('display');
                el.classList.add('p-overlay-mask');
                this.motion.enter();
            } else if (!this.isInitialMount) {
                this.motion.leave().then(() => {
                    if (!this.visible() && this.el?.nativeElement) {
                        (this.el.nativeElement as HTMLElement).style.display = 'none';
                        (this.el.nativeElement as HTMLElement).classList.remove('p-overlay-mask');
                    }
                });
            } else {
                el.style.display = 'none';
            }

            this.isInitialMount = false;
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }

    onClick(event: Event): void {
        if (this.pcSidebar) {
            if (this.pcSidebar.dismissable()) this.pcSidebar.collapse(event);
        } else {
            this.layout?.collapseAll(event);
        }
    }

    onDestroy(): void {
        this.motion?.cancel();
        this.motion = undefined;
    }
}
