import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarHeaderPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_HEADER_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarHeader is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-header',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('header')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_HEADER_INSTANCE, useExisting: SidebarHeader }, { provide: PARENT_INSTANCE, useExisting: SidebarHeader }]
})
export class SidebarHeader extends BaseComponent<SidebarHeaderPassThrough> {
    componentName = 'SidebarHeader';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
