import { Directive, inject } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { SidebarRailPassThrough } from 'primeng/types/sidebar';
import { Sidebar } from './sidebar';
import { SIDEBAR_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarRail is a helper directive for Sidebar component.
 * @group Components
 */
@Directive({
    selector: '[pSidebarRail]',
    standalone: true,
    host: {
        '[class]': "cx('rail')",
        'aria-label': 'Toggle Sidebar',
        title: 'Toggle Sidebar',
        tabindex: '-1',
        type: 'button',
        '(click)': 'onClick($event)'
    },
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarRail }]
})
export class SidebarRail extends BaseComponent<SidebarRailPassThrough> {
    componentName = 'SidebarRail';

    bindDirectiveInstance = inject(Bind, { optional: true, self: true }) ?? undefined;

    _componentStyle = inject(SidebarStyle);

    pcSidebar = inject<Sidebar>(SIDEBAR_INSTANCE, { optional: true }) ?? undefined;

    onAfterViewChecked(): void {
        this.bindDirectiveInstance?.setAttrs(this.ptm('root'));
    }

    onClick(event: Event): void {
        this.pcSidebar?.toggle(event);
    }
}
