import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarMainPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_LAYOUT_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMain is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-main',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('main')",
        '(click)': 'onClick($event)'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarMain }]
})
export class SidebarMain extends BaseComponent<SidebarMainPassThrough> {
    componentName = 'SidebarMain';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    private layout: any = inject(SIDEBAR_LAYOUT_INSTANCE, { optional: true });

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }

    onClick(event: Event): void {
        this.layout?.onMainClick(event);
    }
}
