import { ChangeDetectionStrategy, Component, computed, inject, signal, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarLayoutPassThrough } from 'primeng/types/sidebar';
import type { Sidebar } from './sidebar';
import { SIDEBAR_LAYOUT_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarLayout is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-layout',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('layout')"
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_LAYOUT_INSTANCE, useExisting: SidebarLayout }, { provide: PARENT_INSTANCE, useExisting: SidebarLayout }]
})
export class SidebarLayout extends BaseComponent<SidebarLayoutPassThrough> {
    componentName = 'SidebarLayout';

    bindDirectiveInstance = inject(Bind, { self: true });

    _componentStyle = inject(SidebarStyle);

    private sidebars = new Map<string, Sidebar>();

    private version = signal(0);

    isAnyOpen = computed(() => {
        this.version();
        let open = false;
        this.sidebars.forEach((s) => {
            if (s.open()) open = true;
        });
        return open;
    });

    registerSidebar(id: string, sidebar: Sidebar): void {
        this.sidebars.set(id, sidebar);
        this.version.update((v) => v + 1);
    }

    unregisterSidebar(id: string): void {
        this.sidebars.delete(id);
        this.version.update((v) => v + 1);
    }

    getSidebar(id: string): Sidebar | undefined {
        return this.sidebars.get(id);
    }

    toggle(target?: string, event?: Event): void {
        if (target) {
            this.sidebars.get(target)?.toggle(event);
            return;
        }
        if (this.sidebars.size === 1) {
            this.sidebars.values().next().value?.toggle(event);
        }
    }

    collapseAll(event?: Event): void {
        this.sidebars.forEach((s) => s.collapse(event));
    }

    onMainClick(event: Event): void {
        const target = event.target as HTMLElement | null;
        // Skip clicks that originate from a sidebar trigger so opening the sidebar via the trigger is not immediately undone by the same click.
        if (target?.closest('[data-scope="sidebar"][data-part="trigger"]')) return;
        this.sidebars.forEach((s) => {
            if (s.open() && s.overlay() && s.hideOnOutsideClick()) s.collapse(event);
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
