import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarContentPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_CONTENT_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarContent is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-content',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('content')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_CONTENT_INSTANCE, useExisting: SidebarContent }, { provide: PARENT_INSTANCE, useExisting: SidebarContent }]
})
export class SidebarContent extends BaseComponent<SidebarContentPassThrough> {
    componentName = 'SidebarContent';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
