import { Directive, inject } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { SidebarGroupActionPassThrough } from 'primeng/types/sidebar';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarGroupAction is a helper directive for Sidebar component.
 * @group Components
 */
@Directive({
    selector: '[pSidebarGroupAction]',
    standalone: true,
    host: { '[class]': "cx('groupAction')" },
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarGroupAction }]
})
export class SidebarGroupAction extends BaseComponent<SidebarGroupActionPassThrough> {
    componentName = 'SidebarGroupAction';

    bindDirectiveInstance = inject(Bind, { optional: true, self: true }) ?? undefined;

    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance?.setAttrs(this.ptm('root'));
    }
}
